-- 1. Create Categories table with category_Id primary key and category_name
CREATE TABLE IF NOT EXISTS "Categories" (
    "category_Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "category_name" character varying(150) NOT NULL,
    "category_nameAr" character varying(150) NULL,
    "created_at" timestamp with time zone NOT NULL DEFAULT NOW(),
    CONSTRAINT "UQ_Categories_category_name" UNIQUE ("category_name")
);

-- 2. Ensure category_Id exists in Products table
DO $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name = 'Products' AND column_name = 'category_Id') THEN
        ALTER TABLE "Products" ADD COLUMN "category_Id" INTEGER NULL;
    END IF;
END $$;

-- 3. Populate Categories with predefined & existing categories
INSERT INTO "Categories" ("category_name", "category_nameAr")
VALUES
    ('African Single Origin Roasts', 'محامص إفريقية أحادية المصدر'),
    ('Arabic & Gulf Heritage Roasts', 'تحميص التراث العربي والخليجي'),
    ('Premium Arabic Sweets', 'حلويات عربية فاخرة'),
    ('Premium Chocolates', 'شوكولاتة بلجيكية فاخرة'),
    ('Luxury Chocolates', 'شوكولاتة فاخرة'),
    ('Premium Dates', 'تمور فاخرة ومحشوة'),
    ('Dates & Confections', 'تمور وحلويات'),
    ('Premium Nuts & Dry Fruits', 'مكسرات وفواكه مجففة فاخرة'),
    ('Premium Spices', 'بهارات وتوابل فاخرة'),
    ('Turkish Specialty Roasts', 'قهوة تركية مختصة'),
    ('Coffee Beans', 'حبوب القهوة'),
    ('Specialty Drinks', 'مشروبات مختصة')
ON CONFLICT ("category_name") DO NOTHING;

-- Also insert any other distinct categories from Products table
INSERT INTO "Categories" ("category_name")
SELECT DISTINCT "Category"
FROM "Products"
WHERE "Category" IS NOT NULL AND "Category" <> ''
ON CONFLICT ("category_name") DO NOTHING;

-- 4. Link Products to Categories by category_Id
UPDATE "Products" p
SET "category_Id" = c."category_Id"
FROM "Categories" c
WHERE LOWER(p."Category") = LOWER(c."category_name");

-- 5. Synchronize Categories identity sequence
SELECT setval(
    pg_get_serial_sequence('"Categories"', 'category_Id'),
    COALESCE((SELECT MAX("category_Id") FROM "Categories"), 1),
    true
);

